+.radio-group {
+    display: flex;
+    gap: 1.5rem;
+}
+
+.radio-label {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+    font-size: 0.95rem;
+}
+
+/* Preview Area */
+.preview-area {
+    margin-top: 1.5rem;
+    padding: 1.5rem;
+    border: 1px solid #e0e0e0;
+    border-radius: 8px;
+    transition: all 0.3s ease;
+}
+
+.preview-area h4 {
+    margin-top: 0;
+    margin-bottom: 0.75rem;
+}
+
+.preview-card {
+    padding: 1rem;
+    border: 1px solid #dee2e6;
+    border-radius: 6px;
+    margin-top: 0.75rem;
+}
+
+/* Preview theme variants */
+.preview-theme-light {
+    background: #ffffff;
+    color: #212529;
+}
+
+.preview-theme-dark {
+    background: #1e1e2e;
+    color: #e0e0e0;
+    border-color: #444;
+}
+
+.preview-theme-dark .preview-card {
+    border-color: #555;
+    background: #2a2a3e;
+}
+
+.preview-theme-system {
+    background: #f0f4f8;
+    color: #333;
+}
+
+/* Preview font size variants */
+.preview-font-small {
+    font-size: 0.8rem;
+}
+
+.preview-font-medium {
+    font-size: 1rem;
+}
+
+.preview-font-large {
+    font-size: 1.2rem;
+}
+
+/* Preview compact mode */
+.preview-compact {
+    padding: 0.75rem;
+    line-height: 1.3;
+}
+
+.preview-compact .preview-card {
+    padding: 0.5rem;
+    margin-top: 0.5rem;
+}
+
+/* Loading */
+.loading-spinner {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    padding: 3rem;
+    color: #6c757d;
+    font-size: 1.1rem;
+}
